export const surumCapasi = (no: string) => `v${no.replace(/\./g, "-")}`;

/** Sürümün türü: x.y.0 özellik sürümü, x.y.z yama. */
export const surumTuru = (no: string) => (no.split(".")[2] === "0" ? "Özellik sürümü" : "Yama");
export const surumBul = (no: string) => SURUMLER.find((s) => s.no === no);
export const tarihMetni = (iso: string) => new Date(iso + "T12:00:00").toLocaleDateString("tr-TR", { day: "numeric", month: "long", year: "numeric" });
export const alanAdi = (a: string) => (a === "Studyolar" ? "Stüdyolar" : a);
